-- =============================================================================
-- Seed: validated psychology instruments + library items
-- Source: supabase/seed/validated_scales.json
-- Regenerated by: scripts/generate_validated_scales_seed.py
-- =============================================================================

-- Ensure instruments tables exist (safe if schema already applied).
create table if not exists public.instruments (
  scale_id text primary key,
  name_kr text not null,
  name_en text not null,
  source text,
  response_scale jsonb not null,
  scoring_note text,
  created_at timestamptz not null default now()
);

create table if not exists public.instrument_items (
  id uuid primary key default gen_random_uuid(),
  scale_id text not null references public.instruments (scale_id) on delete cascade,
  variable_name text not null,
  position_in_scale integer not null,
  subscale text,
  reverse_scored boolean not null default false,
  text_kr text not null,
  text_en text not null,
  created_at timestamptz not null default now(),
  constraint instrument_items_scale_variable_unique unique (scale_id, variable_name),
  constraint instrument_items_scale_position_unique unique (scale_id, position_in_scale)
);

-- Idempotent reload of library rows
delete from public.instrument_items where scale_id in (
  'dpes_awe', 'tipi', 'swls', 'prlq', 'spane', 'mvs', 'small_pes', 'awe_sf'
);
delete from public.instruments where scale_id in (
  'dpes_awe', 'tipi', 'swls', 'prlq', 'spane', 'mvs', 'small_pes', 'awe_sf'
);

-- ---- dpes_awe: Dispositional Positive Emotions Scale - Awe Subscale (DPES-Awe) ----

-- ---- tipi: Ten-Item Personality Inventory (TIPI) ----

-- ---- swls: Satisfaction with Life Scale (SWLS) ----

-- ---- prlq: Psychologically Rich Life Questionnaire (PRLQ) ----

-- ---- spane: Scale of Positive and Negative Experience (SPANE) ----

-- ---- mvs: Material Values Scale - Short Form (MVS) ----

-- ---- small_pes: Small Self + Psychological Entitlement Scale (Small_PES) ----

-- ---- awe_sf: Awe Experience Scale - Short Form (AWE-SF) ----

-- =============================================================================
-- Mapping note (application copies library → survey_items on pick):
--   instrument_items.variable_name      → survey_items.variable_name
--   instrument_items.position_in_scale  → survey_items.position_in_scale
--   instrument_items.subscale           → survey_items.subscale
--   instrument_items.reverse_scored     → survey_items.reverse_scored
--   instrument_items.text_kr            → survey_items.item_text_kr (+ item_text default)
--   instrument_items.text_en            → survey_items.item_text_en
--   instruments.scale_id / name_*       → survey_items.source_scale_id / scale_name
--   instruments.response_scale          → survey_items.response_options / anchors
-- =============================================================================
